function Pump([int]$ms){$frame=New-Object Windows.Threading.DispatcherFrame;$timer=New-Object Windows.Threading.DispatcherTimer;$timer.Interval=[TimeSpan]::FromMilliseconds($ms);$timer.Add_Tick({$timer.Stop();$frame.Continue=$false});$timer.Start();[Windows.Threading.Dispatcher]::PushFrame($frame)}
function Shot([string]$path){$dir=Split-Path -Parent $path;if(-not(Test-Path $dir)){[IO.Directory]::CreateDirectory($dir)|Out-Null};$window.UpdateLayout();$a=$window.PointToScreen([Windows.Point]::new(0,0));$b=$window.PointToScreen([Windows.Point]::new($window.ActualWidth,$window.ActualHeight));$w=[Math]::Max(1,[int]($b.X-$a.X));$h=[Math]::Max(1,[int]($b.Y-$a.Y));$bitmap=[Drawing.Bitmap]::new($w,$h);$g=[Drawing.Graphics]::FromImage($bitmap);try{$g.CopyFromScreen([int]$a.X,[int]$a.Y,0,0,[Drawing.Size]::new($w,$h));$bitmap.Save([IO.Path]::GetFullPath($path))}finally{$g.Dispose();$bitmap.Dispose()};"${w}x${h}"}
function Image([int]$width,[int]$height){[HalconDotNet.HObject]$raw=$null;[HalconDotNet.HOperatorSet]::GenImageConst([ref]$raw,'byte',$width,$height);try{New-Object HalconDotNet.HImage($raw)}finally{$raw.Dispose()}}
function Polygon([double[]]$rows,[double[]]$columns){[HalconDotNet.HObject]$x=$null;[HalconDotNet.HOperatorSet]::GenContourPolygonXld([ref]$x,[HalconDotNet.HTuple]$rows,[HalconDotNet.HTuple]$columns);$x}
