$app=[Windows.Application]::Current;if($null-eq$app){$app=New-Object Windows.Application;$app.ShutdownMode=[Windows.ShutdownMode]::OnExplicitShutdown};$window.Left=2;$window.Top=2;$window.Width=1938;$window.Height=1158;$window.Topmost=$true;$window.Show();Pump 600
$flow=F 'flowTools';$main.GetMethod('DisposeFlowTools',$private).Invoke($window,@())|Out-Null;$flow.Clear();$create=$main.GetMethod('CreateFlowTool',$private);$source=$create.Invoke($window,[object[]]@([Enum]::Parse($kindType,'XldPointClosureFilter'),'Contour Quality',$true,$null));$measure=$create.Invoke($window,[object[]]@([Enum]::Parse($kindType,'XldEnclosingCircleDiameterMeasurement'),'Enclosing Circle and Diameter',$true,$null));$judge=$create.Invoke($window,[object[]]@([Enum]::Parse($kindType,'NumericJudge'),'Diameter Judge',$true,$null));$smooth=$create.Invoke($window,[object[]]@([Enum]::Parse($kindType,'XldContourSmoothing'),'Contour Smoothing',$true,$null));$fit=$create.Invoke($window,[object[]]@([Enum]::Parse($kindType,'XldCircleFitting'),'Circle Fit Check',$true,$null));if($null-eq$source-or$null-eq$measure-or$null-eq$judge-or$null-eq$smooth-or$null-eq$fit){throw 'Failed to create S50 UI tools'};$measure.SetInputBinding('XLD',$source.ToolId,'XLD');$judge.SetInputBinding('Value',$measure.ToolId,'Diameter');$judge.InputToolId=$measure.ToolId;$judge.InputPortName='Diameter';$judge.NumericLowerLimit=115;$judge.NumericUpperLimit=125;$smooth.SetInputBinding('XLD',$source.ToolId,'XLD');$fit.SetInputBinding('XLD',$smooth.ToolId,'XLD');foreach($tool in @($source,$measure,$judge,$smooth,$fit)){$flow.Add($tool)}
$angles=0..72|ForEach-Object{$_*[Math]::PI/36};$contour=Polygon ([double[]]($angles|ForEach-Object{255+60*[Math]::Sin($_)})) ([double[]]($angles|ForEach-Object{360+60*[Math]::Cos($_)}));try{$source.SetOutputValue('XLD',$snapshotType.GetMethod('Create',$static).Invoke($null,[object[]]@($contour.PSObject.BaseObject,$source.ToolId,$source.InstanceName,'XLD')));$source.ResultCode='OK'}finally{$contour.Dispose()};$measure.Parameters.XldEnclosingContourMode='All';$measure.Parameters.XldEnclosingMinimumPointCount=2;$measure.Parameters.XldEnclosingClosureTolerance=1;$measure.Parameters.XldEnclosingDiameterMinimum=100;$measure.Parameters.XldEnclosingDiameterMaximum=140;$current=Image 720 520;$main.GetField('currentImage',$private).SetValue($window,$current);$main.GetField('currentImagePath',$private).SetValue($window,'S50 synthetic contour');(F 'viewport').SetImageSize(720,520);$main.GetMethod('ExecuteFlowTool',$private).Invoke($window,[object[]]@($measure,'S50 UI'))|Out-Null;(F 'FlowToolList').SelectedItem=$measure;$main.GetMethod('FlowToolList_SelectionChanged',$private).Invoke($window,[object[]]@((F 'FlowToolList'),$null))|Out-Null;$main.GetMethod('LoadDockConfigurationDraft',$private).Invoke($window,[object[]]@($measure))|Out-Null;(F 'RightTabs').SelectedItem=(F 'DockConfigurationTab');(F 'DockConfigurationTabs').SelectedIndex=0;$main.GetMethod('RefreshUiState',$private).Invoke($window,@())|Out-Null;$main.GetMethod('ScheduleRefreshDisplay',$private).Invoke($window,@())|Out-Null;Pump 900
