$window.WindowState=[Windows.WindowState]::Normal;$window.MinWidth=0;$window.MinHeight=0;$window.Width=1366;$window.Height=768;$window.Left=2;$window.Top=2;Pump 900;$compact=Shot $CompactOutputPath
$main.GetField('recipeCloseConfirmed',$private).SetValue($window,$true);$window.Close();$app.Shutdown();if(Test-Path $temp){Remove-Item -LiteralPath $temp -Recurse -Force};Write-Output "S50_UI_CAPTURE=PASS; Wide=$WideOutputPath; Compact=$CompactOutputPath; Halcon=$HalconOutputPath; WideSize=$wide; CompactSize=$compact; BSB=NOT_IMPLEMENTED_BY_USER_DIRECTIVE"
